style.css:
/* Hide the default YouTube logo */
ytd-topbar-logo-renderer svg {
  display: none !important;
}

/* Apply the Tails GIF */
ytd-topbar-logo-renderer {
  width: 56px !important;
  height: 56px !important;

  background-image: url("https://media.tenor.com/098zQG8yvyUAAAAi/tails-emote-tails.gif");
  background-repeat: no-repeat;
  background-position: center;
  background-size: contain;

  image-rendering: pixelated;
}

/* Optional hover bounce */
ytd-topbar-logo-renderer:hover {
  animation: tailsBounce 0.4s infinite alternate;
}

@keyframes tailsBounce {
  from { transform: translateY(0); }
  to   { transform: translateY(-4px); }
}
